/* mg6_common.h - E4c multi-gesture replay: six real GRABMyo test segments (mg6_data.h, one per
 * class, generated by scripts/sim/gen_e4c.py) through the unchanged E3c pipeline, results
 * published to the E4a mailbox.
 *
 * The replay frame memory (esi_replay_axil) holds one segment at a time: the RV32I writes
 * segment s through WADDR / WDATA_LO / WDATA_HI / WFLAGS while RUN = 0, then runs it
 * MG6_PASSES times. Each run: replay SOFT_RESET (the replay only: DONE, k, counters; checked
 * that no frame is waiting), SEQ_BASE = MG6_SEQ0 + run * MG6_LEN, RUN (no LOOP: exactly MG6_LEN
 * frames). Frame 0 carries SOS, so DSP and CNN clear their stream state at every run (as for a
 * new ESI stream) while the CNN result numbering continues; DSP and CNN are never reset between
 * runs. Every result is checked against the E2 fixed-point decision of its segment (scores,
 * argmax, window end, segment = run number, timestamp = window end, seq), post-processed
 * (K = 1, T = 0) and published before the CNN FIFO is acknowledged.
 * TOHOST: 1 = PASS, otherwise (check << 1) | 1. */
#ifndef MG6_COMMON_H
#define MG6_COMMON_H

/* mbx_common.h / e3c_common.h also define the single-recording helpers (mbx_run,
 * e3c_start, e3c_check) that these programs do not use */
#pragma GCC diagnostic ignored "-Wunused-function"
#include "../mailbox/mbx_common.h"
/* generated by scripts/sim/gen_e4c.py into build/e4c/fw (git-ignored: real GRABMyo samples);
 * built with scripts/sw/build_asm_tests.py --inc build/e4c/fw */
#include "mg6_data.h"

#ifndef MG6_PASSES
#define MG6_PASSES 2u
#endif

#define MG6_RUNS (MG6_NSEG * MG6_PASSES)

/* pipeline as e3c_start(), without starting the replay */
static int mg6_setup(void)
{
    e3c_reset();
    if (!(DSP_STATUS & DSP_ST_IDLE)) return 10;
    if (CNN_STATUS != 0) return 11;
    if (CNN_RESULT_CNT != 0 || CNN_DROP_CNT != 0) return 12;
    if (RPL_FRAME_CNT != 0 || (RPL_STATUS & (RPL_ST_ACTIVE | RPL_ST_DONE))) return 13;
    DSP_SEC_EN = 0xDu;
    DSP_COEF_ADDR = 0;
    for (int i = 0; i < 20; i++) {
        DSP_COEF_DATA = (uint32_t)e3c_dsp_coef[i];
        while (DSP_STATUS & DSP_ST_COEF_PEND) { }
    }
    if (DSP_COEF_ADDR != 20 || DSP_COEF_REJ != 0) return 14;
    RPL_PERIOD = E3C_PERIOD;
    DSP_CTRL = DSP_CTRL_ENABLE;
    CNN_CTRL = CNN_CTRL_ENABLE;
    return 0;
}

/* stop the replay (only it; nothing may be waiting) */
static int mg6_replay_reset(void)
{
    if (RPL_STATUS & RPL_ST_VALID) return 51;
    RPL_CTRL = RPL_CTRL_RESET;
    if (RPL_STATUS & (RPL_ST_ACTIVE | RPL_ST_DONE | RPL_ST_VALID)) return 52;
    return 0;
}

/* segment s -> replay frame memory (RUN = 0) */
static int mg6_load(uint32_t s)
{
    int rc = mg6_replay_reset();
    if (rc) return rc;
    RPL_WADDR = 0;
    for (uint32_t f = 0; f < MG6_LEN; f++) {
        RPL_WDATA_LO = mg6_frames[s][f][0];
        RPL_WDATA_HI = mg6_frames[s][f][1];
        RPL_WFLAGS = (f == 0) ? MG6_FLAG_SOS : 0u;
    }
    if (RPL_WREJ != 0 || RPL_WADDR != MG6_LEN) return 53;
    RPL_NFRAMES = MG6_LEN;
    return 0;
}

/* result `idx` (1-based) = decision d of run `run` (segment run / MG6_PASSES) */
static int mg6_check(const cnn_result_t *r, uint32_t run, uint32_t d, uint32_t idx)
{
    const mg6_result_t *e = &mg6_expected[run / MG6_PASSES][d];
    if (r->index != idx) return 20;
    if (r->end != e->end) return 21;
    if (r->seg != (run & 0xFFu)) return 22;
    if (r->ts != e->end) return 23;                       /* the replay timestamp restarts at every run */
    if (r->seq != MG6_SEQ0 + run * MG6_LEN + e->end) return 24;
    if (r->argmax != e->argmax) return 25;
    for (int c = 0; c < 6; c++)
        if (r->score[c] != e->score[c]) return 26 + c;
    uint32_t best = 0;
    for (uint32_t c = 1; c < 6; c++)
        if (r->score[c] > r->score[best]) best = c;
    if (r->argmax != best) return 33;
    if (r->lat < 100 || r->lat > 20000) return 32;
    return 0;
}

static uint32_t mg6_detect[MG6_NDEC];

static int mg6_run(void)
{
    int rc = e3c_ident();
    if (rc) return rc;
    mbx_init(0);
    pp_reset();
    rc = mg6_setup();
    if (rc) { mbx_error(MBX_ERR_CNN_CHECK); return rc; }
    uint32_t n = 0;
    for (uint32_t run = 0; run < MG6_RUNS; run++) {
        if (run % MG6_PASSES == 0) {
            rc = mg6_load(run / MG6_PASSES);
            if (rc) { mbx_error(MBX_ERR_CNN_CHECK); return rc; }
        }
        rc = mg6_replay_reset();
        if (rc) { mbx_error(MBX_ERR_CNN_CHECK); return rc; }
        RPL_SEQ_BASE = MG6_SEQ0 + run * MG6_LEN;
        RPL_CTRL = RPL_CTRL_RUN;
        for (uint32_t d = 0; d < MG6_NDEC; d++, n++) {
            cnn_result_t r;
            if (mbx_wait(E3C_TIMEOUT)) { mbx_error(MBX_ERR_TIMEOUT); return 40; }
            uint32_t detect = cycles();
            mg6_detect[d] = detect;
            cnn_read(&r);
            rc = mg6_check(&r, run, d, n + 1u);
            if (rc) { mbx_error(rc == 33 ? MBX_ERR_ARGMAX : MBX_ERR_CNN_CHECK); return rc; }
            uint32_t flags = MBX_F_POSTPROC | MBX_F_ARGMAX_OK | MBX_F_GOLDEN_OK;
            if (d == 0) {                       /* every run starts with SOS: new segment */
                pp_reset();
                flags |= MBX_F_NEW_SEGMENT;
            }
            if (run + 1u == MG6_RUNS && d + 1u == MG6_NDEC) flags |= MBX_F_LAST;
            int32_t g = pp_step(r.score);
            mbx_publish(&r, flags, g, detect);
            CNN_RESULT_ACK = 0;
        }
        /* the run's last frame has been sent and accepted before its last result exists */
        if (!(RPL_STATUS & RPL_ST_DONE) || RPL_FRAME_CNT != MG6_LEN) return 54;
#if E3C_PERIOD != 0
        for (uint32_t d = 1; d < MG6_NDEC; d++) {
            uint32_t dt = mg6_detect[d] - mg6_detect[d - 1];
            if (dt < 100u * E3C_PERIOD - 1000u || dt > 100u * E3C_PERIOD + 1000u) return 42;
        }
        if (RPL_LATE_CNT != 0) return 44;
#endif
    }
    if (CNN_DROP_CNT != 0) return 70;
    if (mbx.results != MG6_RUNS * MG6_NDEC) return 71;
    if (mbx.published + mbx.drops + mbx.errors != mbx.results) return 72;
    if (MBX_REG(MBX_H_PRODUCER_INDEX) != mbx.start + mbx.published) return 73;
    MBX_REG(MBX_H_STATE) = MBX_STATE_DONE;
    e3c_reset();
    return 0;
}

#endif
